window.AUTH=window.AUTH||{};window.AUTH["13-894"]={"d":"13-894","id":"2014/13-894","n":"Department of Homeland Security v. MacLean","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for petitioner","date":"2014-07-25","url":"https://www.justice.gov/osg/media/207091/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/department-homeland-sec-v-maclean-brief-merits","n":69},{"k":"reply","label":"Reply brief for petitioner","date":"2014-10-21","url":"https://www.justice.gov/osg/media/234761/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/department-homeland-sec-v-maclean","n":39}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep574/usrep574383/usrep574383.pdf","tr":true,"items":[{"t":"case","label":"Administrator, FAA v. Robertson","cite":"422 U.S. 255","y":1975,"id":"1974/74-450","sc":1,"op":3,"sum":"The SWAP Reports are exempt from public disclosure under Exemption 3 of the FOIA as being \"specifically exempted from disclosure by statute.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 28, 29, 30, 31","1":"10, 11, 15"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"sum":"In a 5-to-4 opinion, the Court held that although the ADA does not force care-givers to treat an \"individual [who] poses a direct threat to the health or safety of others,\" it also prohibits discrimination against any individual \"on the basis of disability in the enjoyment of the services of any place of public accommodation by any person who operates [such] a place.\" The Court then reasoned that since HIV \"substantially limits\" major life activities, such as reproduction, the infection is a \"disability\" that entitles its victims to ADA protections.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"CIA v. Sims","cite":"471 U.S. 159","y":1985,"id":"1984/83-1075","sc":1,"op":1,"ar":3,"sum":"Between 1953 and 1966, the Central Intelligence Agency (CIA) financed a research project, code-named MKULTRA, that was established to counter Soviet and Chinese advances in brainwashing and interrogation techniques. Subprojects were contracted out to various universities, research foundations, and similar institutions. In 1977, respondents in No. 83-1075 (hereafter respondents) filed a request with the CIA under the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"12, 13, 15"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"op":2,"ar":5,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"4, 6"}},{"t":"case","label":"Consumer Prod. Safety Comm’n v. GTE Sylvania, Inc.","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"ar":1,"sum":"Section 6 (b) (1) governs the disclosure of records by the Commission pursuant to a request under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Department of the Treasury v. Federal Labor Relations Auth.","cite":"494 U.S. 922","y":1990,"id":"1989/88-2123","sc":1,"op":1,"sum":"The FLRA erred in holding that the Act requires the IRS to bargain over the NTEU proposal.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","1":"5"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich, L.P.A.","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":"22"}},{"t":"case","label":"MacLean v. Department of Homeland Sec.","cite":"543 F.3d 1145","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/543/1145/","by":{"0":"10, 18, 34","1":"23"}},{"t":"case","label":"Marano v. Department of Justice","cite":"2 F.3d 1137","y":1993,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/2/1137/","by":{"0":"35"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Dabit","cite":"547 U.S. 71","y":2006,"id":"2005/04-1371","sc":1,"sum":"The Court held that \"holder\" class actions such as Dabit's are \"in connection with the purchase or sale\" of a security and therefore are pre-empted by SLUSA.","sumSrc":"Oyez","by":{"0":"31","1":"11"}},{"t":"case","label":"Public Citizen, Inc. v. FAA","cite":"988 F.2d 186","y":1993,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/988/186/","by":{"0":"34"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"op":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 26"}},{"t":"case","label":"Stevens v. Department of the Treasury","cite":"500 U.S. 1","y":1991,"id":"1990/89-1821","sc":1,"sum":"On April 27, 1987, petitioner Stevens, who was in his 60's, was subjected to an adverse personnel action by his employer, the Internal Revenue Service. Believing that he had been the victim of age discrimination, he attempted to invoke his agency's administrative procedure for resolving such claims in September 1987, long after the expiration of the applicable time period set forth in Equal Employment Opportunity …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"sum":"Respondent Williams was indicted by a federal grand jury for alleged violations of 18 U. S. C. § 1014. On his motion, the District Court ordered the indictment dismissed without prejudice because the Government had failed to fulfill its obligation under Circuit precedent to present \"substantial exculpatory evidence\" to the grand jury. Following that precedent, the Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Verizon Commc’ns Inc. v. FCC","cite":"535 U.S. 467","y":2002,"id":"2001/00-511","sc":1,"sum":"The Court held that the FCC can require state commissions to set the rates charged by incumbents for leased elements on a forward-looking basis untied to the incumbents' investment and that the FCC can require incumbents to combine elements of their networks at the request of entrants.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"law","label":"Pub. L. No. 103-272","url":"https://www.govinfo.gov/link/statute/108/1117","by":{"0":"3"}},{"t":"law","label":"American Communities’ Right to Public Information Act, Pub. L. No. 111-83","url":"https://www.govinfo.gov/link/plaw/111/public/83","by":{"0":"41"}},{"t":"law","label":"Pub. L. No. 93-366","url":"https://www.govinfo.gov/link/statute/88/417","by":{"0":"3"}},{"t":"law","label":"Aviation and Transportation Security Act, Pub. L. No. 107-71","url":"https://www.govinfo.gov/link/plaw/107/public/71","by":{"0":"2, 4, 22"}},{"t":"usc","label":"49 U.S.C. § 114","url":"https://www.law.cornell.edu/uscode/text/49/114","subs":["(a)","(d)(1)","(e)(1)","(f)(10)","(r)","(r)(1)","(r)(1)(A)","(r)(1)(C)","(r)(4)(A)","(r)(4)(D)","(r)(2)"],"stext":{"head":"§114. Transportation Security Administration","paras":[[0,"(a) In General.—The Transportation Security Administration shall be an administration of the Department of Homeland Security."],[0,"(b) Leadership.—"],[1,"(1) Head of transportation security administration.—"],[2,"(A) Appointment.—The head of the Administration shall be the Administrator of the Transportation Security Administration (referred to in this section as the \"Administrator\"). The Administrator shall be appointed by the President, by and with the advice and consent of the Senate."],[2,"(B) Qualifications.—The Administrator must—"],[3,"(i) be a citizen of the United States; and"],[3,"(ii) have experience in a field directly related to transportation or security."],[2,"(C) Term.—Effective with respect to any individual appointment by the President, by and with the advice and consent of the Senate, after the date of enactment of the TSA Modernization Act, the term of office of an individual appointed as the Administrator shall be 5 years. The term of office of an individual serving as the Administrator on the date of enactment of the TSA Modernization Act shall be 5 years beginning on the date that the Administrator began serving."],[1,"(2) Deputy administrator.—"],[2,"(A) Appointment.—There is established in the Transportation Security Administration a Deputy Administrator, who shall assist the Administrator in the management of the Transportation Security Administration. The Deputy Administrator shall be appointed by the President."],[2,"(B) Vacancy.—The Deputy Administrator shall be Acting Administrator during the absence or incapacity of the Administrator or during a vacancy in the office of Administrator."],[2,"(C) Qualifications.—The Deputy Administrator must—"],[3,"(i) be a citizen of the United States; and"],[3,"(ii) have experience in a field directly related to transportation or security."],[1,"(3) Chief counsel.—"],[2,"(A) Appointment.—There is established in the Transportation Security Administration a Chief Counsel, who shall advise the Administrator and other senior officials on all legal matters relating to the responsibilities, functions, and management of the Transportation Security Administration."],[2,"(B) Qualifications.—The Chief Counsel must be a citizen of the United States."],[0,"(c) Limitation on Ownership of Stocks and Bonds.—The Administrator may not own stock in or bonds of a transportation or security enterprise or an enterprise that makes equipment that could be used for security purposes."],[0,"(d) Functions.—The Administrator shall be responsible for security in all modes of transportation, including—"],[1,"(1) carrying out chapter 449, relating to civil aviation security, and related research and development activities; and"],[1,"(2) security responsibilities over other modes of transportation that are exercised by the Department of Transportation."],[0,"(e) Screening Operations.—The Administrator shall—"],[1,"(1) be responsible for day-to-day Federal security screening operations for passenger air transportation and intrastate air transportation under sections 44901 and 44935;"],[1,"(2) develop standards for the hiring and retention of security screening personnel;"],[1,"(3) train and test security screening personnel; and"],[1,"(4) be responsible for hiring and training personnel to provide security screening at all airports in the United States where screening is required under section 44901, in consultation with the Secretary of Transportation and the heads of other appropriate Federal agencies and departments."],[0,"(f) Additional Duties and Powers.—In addition to carrying out the functions specified in subsections (d) and (e), the Administrator shall—"],[1,"(1) receive, assess, and distribute intelligence information related to transportation security;"],[1,"(2) assess threats to transportation;"],[1,"(3) develop policies, strategies, and plans for dealing with threats to transportation security;"],[1,"(4) make other plans related to transportation security, including coordinating countermeasures with appropriate departments, agencies, and instrumentalities of the United States Government;"],[1,"(5) serve as the primary liaison for transportation security to the intelligence and law enforcement communities;"],[1,"(6) on a day-to-day basis, manage and provide operational guidance to the field security resources of the Administration, including Federal Security Managers as provided by section 44933;"],[1,"(7) enforce security-related regulations and requirements;"],[1,"(8) identify and undertake research and development activities necessary to enhance transportation security;"],[1,"(9) inspect, maintain, and test security facilities, equipment, and systems;"],[1,"(10) ensure the adequacy of security measures for the transportation of cargo;"],[1,"(11) oversee the implementation, and ensure the adequacy, of security measures at airports and other transportation facilities;"],[1,"(12) require background checks for airport security screening personnel, individuals with access to secure areas of airports, and other transportation security personnel;"],[1,"(13) work in conjunction with the Administrator of the Federal Aviation Administration with respect to any actions or activities that may affect aviation safety or air carrier operations;"],[1,"(14) work with the International Civil Aviation Organization and appropriate aeronautic authorities of foreign governments under section 44907 to address security concerns on passenger flights by foreign air carriers in foreign air transportation;"],[1,"(15) establish and maintain a National Deployment Office as required under section 44948 of this title; and"],[1,"(16) carry out such other duties, and exercise such other powers, relating to transportation security as the Administrator considers appropriate, to the extent authorized by law."],[0,"(g) National Emergency Responsibilities.—"],[1,"(1) In general.—Subject to the direction and control of the Secretary of Homeland Security, the Administrator, during a national emergency, shall have the following responsibilities:"],[2,"(A) To coordinate domestic transportation, including aviation, rail, and other surface transportation, and maritime transportation (including port security)."],[2,"(B) To coordinate and oversee the transportation-related responsibilities of other departments and agencies of the Federal Government other than the Department of Defense and the military departments."],[2,"(C) To coordinate and provide notice to other departments and agencies of the Federal Government, and appropriate agencies of State and local governments, including departments and agencies for transportation, law enforcement, and border control, about threats to transportation."],[2,"(D) To carry out such other duties, and exercise such other powers, relating to transportation during a national emergency as the Secretary of Homeland Security shall prescribe."],[1,"(2) Authority of other departments and agencies.—The authority of the Administrator under this subsection shall not supersede the authority of any other department or agency of the Federal Government under law with respect to transportation or transportation-related matters, whether or not during a national emergency."],[1,"(3) Circumstances.—The Secretary of Homeland Security shall prescribe the circumstances constituting a national emergency for purposes of this subsection."],[0,"(h) Management of Security Information.—In consultation with the Transportation Security Oversight Board, the Administrator shall—"],[1,"(1) enter into memoranda of understanding with Federal agencies or other entities to share or otherwise cross-check as necessary data on individuals identified on Federal agency databases who may pose a risk to transportation or national security;"],[1,"(2) establish procedures for notifying the Administrator of the Federal Aviation Administration, appropriate State and local law enforcement officials, and airport or airline security officers of the identity of individuals known to pose, or suspected of posing, a risk of air piracy or terrorism or a threat to airline or passenger safety;"],[1,"(3) in consultation with other appropriate Federal agencies and air carriers, establish policies and procedures requiring air carriers—"],[2,"(A) to use information from government agencies to identify individuals on passenger lists who may be a threat to civil aviation or national security; and"],[2,"(B) if such an individual is identified, notify appropriate law enforcement agencies, prevent the individual from boarding an aircraft, or take other appropriate action with respect to that individual; and"],[1,"(4) consider requiring passenger air carriers to share passenger lists with appropriate Federal agencies for the purpose of identifying individuals who may pose a threat to aviation safety or national security."],[0,"(i) View of NTSB.—In taking any action under this section that could affect safety, the Administrator shall give great weight to the timely views of the National Transportation Safety Board."],[0,"(j) Acquisitions.—"],[1,"(1) In general.—The Administrator is authorized—"],[2,"(A) to acquire (by purchase, lease, condemnation, or otherwise) such real property, or any interest therein, within and outside the continental United States, as the Administrator considers necessary;"],[2,"(B) to acquire (by purchase, lease, condemnation, or otherwise) and to construct, repair, operate, and maintain such personal property (including office space and patents), or any interest therein, within and outside the continental United States, as the Administrator considers necessary;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/114?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§114. Transportation Security Administration","tname":"Transportation","by":{"0":"2, 2, 2, 2, 2, 2, passim, passim, 28, 12, 17, 18, 37, 41, 41","1":"passim, 18, 23, 23"}},{"t":"law","label":"Pub. L. No. 95-454","url":"https://www.govinfo.gov/link/statute/92/1116","by":{"0":"20, 25"}},{"t":"law","label":"Pub. L. No. 110-161","url":"https://www.govinfo.gov/link/plaw/110/public/161","by":{"0":"4"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","subs":["(b)(3)(1970)","(b)(3)(1976)"],"stext":{"head":"§552. Public information; agency rules, opinions, orders, records, and proceedings","paras":[[0,"(a) Each agency shall make available to the public information as follows:"],[0,"(1) Each agency shall separately state and currently publish in the Federal Register for the guidance of the public—"],[1,"(A) descriptions of its central and field organization and the established places at which, the employees (and in the case of a uniformed service, the members) from whom, and the methods whereby, the public may obtain information, make submittals or requests, or obtain decisions;"],[1,"(B) statements of the general course and method by which its functions are channeled and determined, including the nature and requirements of all formal and informal procedures available;"],[1,"(C) rules of procedure, descriptions of forms available or the places at which forms may be obtained, and instructions as to the scope and contents of all papers, reports, or examinations;"],[1,"(D) substantive rules of general applicability adopted as authorized by law, and statements of general policy or interpretations of general applicability formulated and adopted by the agency; and"],[1,"(E) each amendment, revision, or repeal of the foregoing."],[0,"Except to the extent that a person has actual and timely notice of the terms thereof, a person may not in any manner be required to resort to, or be adversely affected by, a matter required to be published in the Federal Register and not so published. For the purpose of this paragraph, matter reasonably available to the class of persons affected thereby is deemed published in the Federal Register when incorporated by reference therein with the approval of the Director of the Federal Register."],[0,"(2) Each agency, in accordance with published rules, shall make available for public inspection in an electronic format—"],[1,"(A) final opinions, including concurring and dissenting opinions, as well as orders, made in the adjudication of cases;"],[1,"(B) those statements of policy and interpretations which have been adopted by the agency and are not published in the Federal Register;"],[1,"(C) administrative staff manuals and instructions to staff that affect a member of the public;"],[1,"(D) copies of all records, regardless of form or format—"],[2,"(i) that have been released to any person under paragraph (3); and"],[2,"(ii)(I) that because of the nature of their subject matter, the agency determines have become or are likely to become the subject of subsequent requests for substantially the same records; or"],[2,"(II) that have been requested 3 or more times; and"],[1,"(E) a general index of the records referred to under subparagraph (D);"],[0,"unless the materials are promptly published and copies offered for sale. For records created on or after November 1, 1996, within one year after such date, each agency shall make such records available, including by computer telecommunications or, if computer telecommunications means have not been established by the agency, by other electronic means. To the extent required to prevent a clearly unwarranted invasion of personal privacy, an agency may delete identifying details when it makes available or publishes an opinion, statement of policy, interpretation, staff manual, instruction, or copies of records referred to in subparagraph (D). However, in each case the justification for the deletion shall be explained fully in writing, and the extent of such deletion shall be indicated on the portion of the record which is made available or published, unless including that indication would harm an interest protected by the exemption in subsection (b) under which the deletion is made. If technically feasible, the extent of the deletion shall be indicated at the place in the record where the deletion was made. Each agency shall also maintain and make available for public inspection in an electronic format current indexes providing identifying information for the public as to any matter issued, adopted, or promulgated after July 4, 1967, and required by this paragraph to be made available or published. Each agency shall promptly publish, quarterly or more frequently, and distribute (by sale or otherwise) copies of each index or supplements thereto unless it determines by order published in the Federal Register that the publication would be unnecessary and impracticable, in which case the agency shall nonetheless provide copies of such index on request at a cost not to exceed the direct cost of duplication. Each agency shall make the index referred to in subparagraph (E) available by computer telecommunications by December 31, 1999. A final order, opinion, statement of policy, interpretation, or staff manual or instruction that affects a member of the public may be relied on, used, or cited as precedent by an agency against a party other than an agency only if—"],[1,"(i) it has been indexed and either made available or published as provided by this paragraph; or"],[1,"(ii) the party has actual and timely notice of the terms thereof."],[0,"(3)(A) Except with respect to the records made available under paragraphs (1) and (2) of this subsection, and except as provided in subparagraph (E), each agency, upon any request for records which (i) reasonably describes such records and (ii) is made in accordance with published rules stating the time, place, fees (if any), and procedures to be followed, shall make the records promptly available to any person."],[0,"(B) In making any record available to a person under this paragraph, an agency shall provide the record in any form or format requested by the person if the record is readily reproducible by the agency in that form or format. Each agency shall make reasonable efforts to maintain its records in forms or formats that are reproducible for purposes of this section."],[0,"(C) In responding under this paragraph to a request for records, an agency shall make reasonable efforts to search for the records in electronic form or format, except when such efforts would significantly interfere with the operation of the agency's automated information system."],[0,"(D) For purposes of this paragraph, the term \"search\" means to review, manually or by automated means, agency records for the purpose of locating those records which are responsive to a request."],[0,"(E) An agency, or part of an agency, that is an element of the intelligence community (as that term is defined in section 3(4) of the National Security Act of 1947 (50 U.S.C. 401a(4))) 1 shall not make any record available under this paragraph to—"],[1,"(i) any government entity, other than a State, territory, commonwealth, or district of the United States, or any subdivision thereof; or"],[1,"(ii) a representative of a government entity described in clause (i)."],[0,"(4)(A)(i) In order to carry out the provisions of this section, each agency shall promulgate regulations, pursuant to notice and receipt of public comment, specifying the schedule of fees applicable to the processing of requests under this section and establishing procedures and guidelines for determining when such fees should be waived or reduced. Such schedule shall conform to the guidelines which shall be promulgated, pursuant to notice and receipt of public comment, by the Director of the Office of Management and Budget and which shall provide for a uniform schedule of fees for all agencies."],[0,"(ii) Such agency regulations shall provide that—"],[1,"(I) fees shall be limited to reasonable standard charges for document search, duplication, and review, when records are requested for commercial use;"],[1,"(II) fees shall be limited to reasonable standard charges for document duplication when records are not sought for commercial use and the request is made by an educational or noncommercial scientific institution, whose purpose is scholarly or scientific research; or a representative of the news media; and"],[1,"(III) for any request not described in (I) or (II), fees shall be limited to reasonable standard charges for document search and duplication."],[0,"In this clause, the term \"a representative of the news media\" means any person or entity that gathers information of potential interest to a segment of the public, uses its editorial skills to turn the raw materials into a distinct work, and distributes that work to an audience. In this clause, the term \"news\" means information that is about current events or that would be of current interest to the public. Examples of news-media entities are television or radio stations broadcasting to the public at large and publishers of periodicals (but only if such entities qualify as disseminators of \"news\") who make their products available for purchase by or subscription by or free distribution to the general public. These examples are not all-inclusive. Moreover, as methods of news delivery evolve (for example, the adoption of the electronic dissemination of newspapers through telecommunications services), such alternative media shall be considered to be news-media entities. A freelance journalist shall be regarded as working for a news-media entity if the journalist can demonstrate a solid basis for expecting publication through that entity, whether or not the journalist is actually employed by the entity. A publication contract would present a solid basis for such an expectation; the Government may also consider the past publication record of the requester in making such a determination."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/552?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§552. Public information; agency rules, opinions, orders, records, and proceedings","tname":"Government Organization and Employees","by":{"0":"3, 4, 28, 31, 34, 29, 32","1":"10, 10"}},{"t":"law","label":"Pub. L. No. 107-296","url":"https://www.govinfo.gov/link/plaw/107/public/296","by":{"0":"3","1":"15"}},{"t":"usc","label":"50 U.S.C. § 403","url":"https://www.law.cornell.edu/uscode/text/50/403","subs":["(d)(3)(1976)"],"tname":"War and National Defense","by":{"0":"15","1":"12"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)(1976)","(b)","(b)(B)","(d)(1976)"],"by":{"0":"28, 22, 21, 28"}},{"t":"usc","label":"5 U.S.C. § 1211","url":"https://www.law.cornell.edu/uscode/text/5/1211","by":{"0":"36"}},{"t":"usc","label":"5 U.S.C. § 1213","url":"https://www.law.cornell.edu/uscode/text/5/1213","subs":["(b)","(c)","(e)","(h)"],"stext":{"head":"§1213. Provisions relating to disclosures of violations of law, gross mismanagement, and certain other matters","paras":[[0,"(a) This section applies with respect to—"],[1,"(1) any disclosure of information by an employee, former employee, or applicant for employment which the employee, former employee, or applicant reasonably believes evidences—"],[2,"(A) a violation of any law, rule, or regulation; or"],[2,"(B) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety;"],[1,"if such disclosure is not specifically prohibited by law and if such information is not specifically required by Executive order to be kept secret in the interest of national defense or the conduct of foreign affairs; and"],[1,"(2) any disclosure by an employee, former employee, or applicant for employment to the Special Counsel or to the Inspector General of an agency or another employee designated by the head of the agency to receive such disclosures of information which the employee, former employee, or applicant reasonably believes evidences—"],[2,"(A) a violation of any law, rule, or regulation; or"],[2,"(B) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety."],[0,"(b) Whenever the Special Counsel receives information of a type described in subsection (a) of this section, the Special Counsel shall review such information and, within 45 days after receiving the information, determine whether there is a substantial likelihood that the information discloses a violation of any law, rule, or regulation, or gross mismanagement, gross waste of funds, abuse of authority, or substantial and specific danger to public health and safety."],[0,"(c)(1) Subject to paragraph (2), if the Special Counsel makes a positive determination under subsection (b) of this section, the Special Counsel shall promptly transmit the information with respect to which the determination was made to the appropriate agency head and require that the agency head—"],[1,"(A) conduct an investigation with respect to the information and any related matters transmitted by the Special Counsel to the agency head; and"],[1,"(B) submit a written report setting forth the findings of the agency head within 60 days after the date on which the information is transmitted to the agency head or within any longer period of time agreed to in writing by the Special Counsel."],[0,"(2) The Special Counsel may require an agency head to conduct an investigation and submit a written report under paragraph (1) only if the information was transmitted to the Special Counsel by—"],[1,"(A) an employee, former employee, or applicant for employment in the agency which the information concerns; or"],[1,"(B) an employee who obtained the information in connection with the performance of the employee's duties and responsibilities."],[0,"(d) Any report required under subsection (c) shall be reviewed and signed by the head of the agency and shall include—"],[1,"(1) a summary of the information with respect to which the investigation was initiated;"],[1,"(2) a description of the conduct of the investigation;"],[1,"(3) a summary of any evidence obtained from the investigation;"],[1,"(4) a listing of any violation or apparent violation of any law, rule, or regulation; and"],[1,"(5) a description of any action taken or planned as a result of the investigation, such as—"],[2,"(A) changes in agency rules, regulations, or practices;"],[2,"(B) the restoration of any aggrieved employee;"],[2,"(C) disciplinary action against any employee; and"],[2,"(D) referral to the Attorney General of any evidence of a criminal violation."],[0,"(e)(1) Any report required under subsection (c) or paragraph (5) of this subsection shall be submitted to the Special Counsel, and the Special Counsel shall transmit a copy to the complainant, except as provided under subsection (f) of this section. The complainant may submit comments to the Special Counsel on the agency report within 15 days of having received a copy of the report."],[0,"(2) Upon receipt of any report that the head of an agency is required to submit under subsection (c), the Special Counsel shall review the report and determine whether—"],[1,"(A) the findings of the head of the agency appear reasonable; and"],[1,"(B) if the Special Counsel requires the head of the agency to submit a supplemental report under paragraph (5), the reports submitted by the head of the agency collectively contain the information required under subsection (d)."],[0,"(3) The Special Counsel shall transmit any report submitted to the Special Counsel by the head of an agency under subsection (c) or paragraph (5) of this subsection, any comments provided by the complainant pursuant to subsection (e)(1), and any appropriate comments or recommendations by the Special Counsel to the President and the congressional committees with jurisdiction over the agency which the disclosure involves."],[0,"(4) Whenever the Special Counsel does not receive the report of the agency within the time prescribed in subsection (c)(2) of this section, the Special Counsel shall transmit a copy of the information which was transmitted to the agency head to the President and the congressional committees with jurisdiction over the agency which the disclosure involves together with a statement noting the failure of the head of the agency to file the required report."],[0,"(5) If, after conducting a review of a report under paragraph (2), the Special Counsel concludes that the Special Counsel requires additional information or documentation to determine whether the report submitted by the head of an agency is reasonable and sufficient, the Special Counsel may request that the head of the agency submit a supplemental report—"],[1,"(A) containing the additional information or documentation identified by the Special Counsel; and"],[1,"(B) that the head of the agency shall submit to the Special Counsel within a period of time specified by the Special Counsel."],[0,"(f) In any case in which evidence of a criminal violation obtained by an agency in an investigation under subsection (c) of this section is referred to the Attorney General—"],[1,"(1) the report shall not be transmitted to the complainant; and"],[1,"(2) the agency shall notify the Office of Personnel Management and the Office of Management and Budget of the referral."],[0,"(g)(1) If the Special Counsel receives information of a type described in subsection (a) from an individual other than an individual described in subparagraph (A) or (B) of subsection (c)(2), the Special Counsel may transmit the information to the head of the agency which the information concerns. The head of such agency shall, within a reasonable time after the information is transmitted, inform the Special Counsel in writing of what action has been or is being taken and when such action shall be completed. The Special Counsel shall inform the individual of the report of the agency head."],[0,"(2) If the Special Counsel receives information of a type described in subsection (a) from an individual described in subparagraph (A) or (B) of subsection (c)(2), but does not make a positive determination under subsection (b), the Special Counsel may transmit the information to the head of the agency which the information concerns, except that the information may not be transmitted to the head of the agency without the consent of the individual. The head of such agency shall, within a reasonable time after the information is transmitted, inform the Special Counsel in writing of what action has been or is being taken and when such action will be completed. The Special Counsel shall inform the individual of the report of the agency head."],[0,"(3) If the Special Counsel does not transmit the information to the head of the agency under paragraph (2), the Special Counsel shall inform the individual of—"],[1,"(A) the reasons why the disclosure may not be further acted on under this chapter; and"],[1,"(B) other offices available for receiving disclosures, should the individual wish to pursue the matter further."],[0,"(h) The identity of any individual who makes a disclosure described in subsection (a) may not be disclosed by the Special Counsel without such individual's consent unless the Special Counsel determines that the disclosure of the individual's identity is necessary because of an imminent danger to public health or safety or imminent violation of any criminal law."],[0,"(i) Except as specifically authorized under this section, the provisions of this section shall not be considered to authorize disclosure of any information by any agency or any person which is—"],[1,"(1) specifically prohibited from disclosure by any other provision of law; or"],[1,"(2) specifically required by Executive order to be kept secret in the interest of national defense or the conduct of foreign affairs."],[0,"(j) With respect to any disclosure of information described in subsection (a) which involves foreign intelligence or counterintelligence information, if the disclosure is specifically prohibited by law or by Executive order, the Special Counsel shall transmit such information to the National Security Advisor, the Permanent Select Committee on Intelligence of the House of Representatives, and the Select Committee on Intelligence of the Senate."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/1213?type=usc&year=mostrecent&link-type=html"},"head":"§1213. Provisions relating to disclosures of violations of law, gross mismanagement, and certain other matters","tname":"Government Organization and Employees","by":{"0":"36, 36, 36, 36","1":"24"}},{"t":"usc","label":"5 U.S.C. § 2302","url":"https://www.law.cornell.edu/uscode/text/5/2302","subs":["(b)(8)","(b)(8)(A)","(b)(8)(A)(i)(2006)","(b)(8)(A)(i)","(b)(8)(A)(ii)","(b)(8)(B)","(b)(8)(B)(i)(2006)","(b)(8)(B)(i)","(b)(8)(B)(ii)","(a)(2)(D)","(b)","(e)(1)(H)"],"stext":{"head":"§2302. Prohibited personnel practices","paras":[[0,"(a)(1) For the purpose of this title, \"prohibited personnel practice\" means any action described in subsection (b)."],[0,"(2) For the purpose of this section—"],[1,"(A) \"personnel action\" means—"],[2,"(i) an appointment;"],[2,"(ii) a promotion;"],[2,"(iii) an action under chapter 75 of this title or other disciplinary or corrective action;"],[2,"(iv) a detail, transfer, or reassignment;"],[2,"(v) a reinstatement;"],[2,"(vi) a restoration;"],[2,"(vii) a reemployment;"],[2,"(viii) a performance evaluation under chapter 43 of this title or under title 38;"],[2,"(ix) a decision concerning pay, benefits, or awards, or concerning education or training if the education or training may reasonably be expected to lead to an appointment, promotion, performance evaluation, or other action described in this subparagraph;"],[2,"(x) a decision to order psychiatric testing or examination;"],[2,"(xi) the implementation or enforcement of any nondisclosure policy, form, or agreement; and"],[2,"(xii) any other significant change in duties, responsibilities, or working conditions;"],[1,"with respect to an employee in, or applicant for, a covered position in an agency, and in the case of an alleged prohibited personnel practice described in subsection (b)(8), an employee or applicant for employment in a Government corporation as defined in section 9101 of title 31;"],[1,"(B) \"covered position\" means, with respect to any personnel action, any position in the competitive service, a career appointee position in the Senior Executive Service, or a position in the excepted service, but does not include any position which is, prior to the personnel action—"],[2,"(i) excepted from the competitive service because of its confidential, policy-determining, policy-making, or policy-advocating character; or"],[2,"(ii) excluded from the coverage of this section by the President based on a determination by the President that it is necessary and warranted by conditions of good administration;"],[1,"(C) \"agency\" means an Executive agency and the Government Publishing Office, but does not include—"],[2,"(i) a Government corporation, except in the case of an alleged prohibited personnel practice described under subsection (b)(8) or section 2302(b)(9)(A)(i), (B), (C), or (D);"],[2,"(ii)(I) the Federal Bureau of Investigation, the Central Intelligence Agency, the Defense Intelligence Agency, the National Geospatial-Intelligence Agency, the National Security Agency, the Office of the Director of National Intelligence, and the National Reconnaissance Office; and"],[2,"(II) as determined by the President, any executive agency or unit thereof the principal function of which is the conduct of foreign intelligence or counterintelligence activities, provided that the determination be made prior to a personnel action; or"],[2,"(iii) the Government Accountability Office; and"],[1,"(D) \"disclosure\" means a formal or informal communication or transmission, but does not include a communication concerning policy decisions that lawfully exercise discretionary authority unless the employee or applicant providing the disclosure reasonably believes that the disclosure evidences—"],[2,"(i) any violation of any law, rule, or regulation; or"],[2,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety."],[0,"(b) Any employee who has authority to take, direct others to take, recommend, or approve any personnel action, shall not, with respect to such authority—"],[1,"(1) discriminate for or against any employee or applicant for employment—"],[2,"(A) on the basis of race, color, religion, sex, or national origin, as prohibited under section 717 of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16);"],[2,"(B) on the basis of age, as prohibited under sections 12 and 15 of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 631, 633a);"],[2,"(C) on the basis of sex, as prohibited under section 6(d) of the Fair Labor Standards Act of 1938 (29 U.S.C. 206(d));"],[2,"(D) on the basis of handicapping condition, as prohibited under section 501 of the Rehabilitation Act of 1973 (29 U.S.C. 791); or"],[2,"(E) on the basis of marital status or political affiliation, as prohibited under any law, rule, or regulation;"],[1,"(2) solicit or consider any recommendation or statement, oral or written, with respect to any individual who requests or is under consideration for any personnel action unless such recommendation or statement is based on the personal knowledge or records of the person furnishing it and consists of—"],[2,"(A) an evaluation of the work performance, ability, aptitude, or general qualifications of such individual; or"],[2,"(B) an evaluation of the character, loyalty, or suitability of such individual;"],[1,"(3) coerce the political activity of any person (including the providing of any political contribution or service), or take any action against any employee or applicant for employment as a reprisal for the refusal of any person to engage in such political activity;"],[1,"(4) deceive or willfully obstruct any person with respect to such person's right to compete for employment;"],[1,"(5) influence any person to withdraw from competition for any position for the purpose of improving or injuring the prospects of any other person for employment;"],[1,"(6) grant any preference or advantage not authorized by law, rule, or regulation to any employee or applicant for employment (including defining the scope or manner of competition or the requirements for any position) for the purpose of improving or injuring the prospects of any particular person for employment;"],[1,"(7) appoint, employ, promote, advance, or advocate for appointment, employment, promotion, or advancement, in or to a civilian position any individual who is a relative (as defined in section 3110(a)(3) of this title) of such employee if such position is in the agency in which such employee is serving as a public official (as defined in section 3110(a)(2) of this title) or over which such employee exercises jurisdiction or control as such an official;"],[1,"(8) take or fail to take, or threaten to take or fail to take, a personnel action with respect to any employee or applicant for employment because of—"],[2,"(A) any disclosure of information by an employee or applicant which the employee or applicant reasonably believes evidences—"],[3,"(i) any violation of any law, rule, or regulation, or"],[3,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety,"],[2,"if such disclosure is not specifically prohibited by law and if such information is not specifically required by Executive order to be kept secret in the interest of national defense or the conduct of foreign affairs;"],[2,"(B) any disclosure to the Special Counsel, or to the Inspector General of an agency or another employee designated by the head of the agency to receive such disclosures, of information which the employee or applicant reasonably believes evidences—"],[3,"(i) any violation (other than a violation of this section) of any law, rule, or regulation, or"],[3,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety; or"],[2,"(C) any disclosure to Congress (including any committee of Congress) by any employee of an agency or applicant for employment at an agency of information described in subparagraph (B) that is—"],[3,"(i) not classified; or"],[3,"(ii) if classified—"],[4,"(I) has been classified by the head of an agency that is not an element of the intelligence community (as defined by section 3 of the National Security Act of 1947 (50 U.S.C. 3003)); and"],[4,"(II) does not reveal intelligence sources and methods.1"],[1,"(9) take or fail to take, or threaten to take or fail to take, any personnel action against any employee or applicant for employment because of—"],[2,"(A) the exercise of any appeal, complaint, or grievance right granted by any law, rule, or regulation—"],[3,"(i) with regard to remedying a violation of paragraph (8); or"],[3,"(ii) other than with regard to remedying a violation of paragraph (8);"],[2,"(B) testifying for or otherwise lawfully assisting any individual in the exercise of any right referred to in subparagraph (A)(i) or (ii);"],[2,"(C) cooperating with or disclosing information to the Inspector General (or any other component responsible for internal investigation or review) of an agency, or the Special Counsel, in accordance with applicable provisions of law; or"],[2,"(D) refusing to obey an order that would require the individual to violate a law, rule, or regulation;"],[1,"(10) discriminate for or against any employee or applicant for employment on the basis of conduct which does not adversely affect the performance of the employee or applicant or the performance of others; except that nothing in this paragraph shall prohibit an agency from taking into account in determining suitability or fitness any conviction of the employee or applicant for any crime under the laws of any State, of the District of Columbia, or of the United States;"],[1,"(11)(A) knowingly take, recommend, or approve any personnel action if the taking of such action would violate a veterans' preference requirement; or"],[1,"(B) knowingly fail to take, recommend, or approve any personnel action if the failure to take such action would violate a veterans' preference requirement;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/2302?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§2302. Prohibited personnel practices","tname":"Government Organization and Employees","by":{"0":"15, 16, 35, 36, 37, passim, 9, 9, 35, 36, 9, 17, 35, 40, 15, 17, 36, 36, 35, 35","1":"23, 23, 23, 23, 23, 23, 23"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(d)"],"stext":{"head":"§7513. Cause and procedure","paras":[[0,"(a) Under regulations prescribed by the Office of Personnel Management, an agency may take an action covered by this subchapter against an employee only for such cause as will promote the efficiency of the service."],[0,"(b) An employee against whom an action is proposed is entitled to—"],[1,"(1) at least 30 days' advance written notice, unless there is reasonable cause to believe the employee has committed a crime for which a sentence of imprisonment may be imposed, stating the specific reasons for the proposed action;"],[1,"(2) a reasonable time, but not less than 7 days, to answer orally and in writing and to furnish affidavits and other documentary evidence in support of the answer;"],[1,"(3) be represented by an attorney or other representative; and"],[1,"(4) a written decision and the specific reasons therefor at the earliest practicable date."],[0,"(c) An agency may provide, by regulation, for a hearing which may be in lieu of or in addition to the opportunity to answer provided under subsection (b)(2) of this section."],[0,"(d) An employee against whom an action is taken under this section is entitled to appeal to the Merit Systems Protection Board under section 7701 of this title."],[0,"(e) Copies of the notice of proposed action, the answer of the employee when written, a summary thereof when made orally, the notice of decision and reasons therefor, and any order effecting an action covered by this subchapter, together with any supporting material, shall be maintained by the agency and shall be furnished to the Board upon its request and to the employee affected upon the employee's request."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7513?type=usc&year=mostrecent&link-type=html"},"head":"§7513. Cause and procedure","tname":"Government Organization and Employees","by":{"0":"9","1":"23"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(a)(1)(2006)","(b)(1)(2006)"],"by":{"0":"10, 10"}},{"t":"usc","label":"18 U.S.C. § 1905","url":"https://www.law.cornell.edu/uscode/text/18/1905","subs":["(1976)"],"by":{"0":"19, 20, 25"}},{"t":"usc","label":"49 U.S.C. § 1504","url":"https://www.law.cornell.edu/uscode/text/49/1504","subs":["(1970)"],"tname":"Transportation","by":{"0":"29","1":"11"}},{"t":"usc","label":"49 U.S.C. § 40119","url":"https://www.law.cornell.edu/uscode/text/49/40119","subs":["(b)(2000)","(b)"],"stext":{"head":"§40119. Sensitive security information","paras":[[0,"(a) Disclosure.—"],[1,"(1) Regulations prohibiting disclosure.—Notwithstanding the establishment of a Department of Homeland Security, the Secretary of Transportation, in accordance with section 552(b)(3)(B) of title 5, shall prescribe regulations prohibiting disclosure of information obtained or developed in ensuring security under this title if the Secretary of Transportation decides disclosing the information would—"],[2,"(A) be an unwarranted invasion of personal privacy;"],[2,"(B) reveal a trade secret or privileged or confidential commercial or financial information; or"],[2,"(C) be detrimental to transportation safety."],[1,"(2) Disclosure to congress.—Paragraph (1) shall not be construed to authorize information to be withheld from a committee of Congress authorized to have such information."],[1,"(3) Rule of construction.—Nothing in paragraph (1) shall be construed to authorize the designation of information as sensitive security information (as such term is defined in section 15.5 of title 49, Code of Federal Regulations) to—"],[2,"(A) conceal a violation of law, inefficiency, or administrative error;"],[2,"(B) prevent embarrassment to a person, organization, or agency;"],[2,"(C) restrain competition; or"],[2,"(D) prevent or delay the release of information that does not require protection in the interest of transportation security, including basic scientific research information not clearly related to transportation security."],[1,"(4) Law enforcement disclosure.—Section 552a of title 5 shall not apply to disclosures that the Administrator may make from the systems of records of the Federal Aviation Administration to any Federal law enforcement, intelligence, protective service, immigration, or national security official in order to assist the official receiving the information in the performance of official duties."],[0,"(b) Transfers of Duties and Powers Prohibited.—Except as otherwise provided by law, a duty or power under this section may not be transferred to another department, agency, or instrumentality of the Federal Government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/40119?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§40119. Sensitive security information","tname":"Transportation","by":{"0":"3, 4, 10, 41"}},{"t":"usc","label":"49 U.S.C. § 44917","url":"https://www.law.cornell.edu/uscode/text/49/44917","subs":["(a)(1)"],"stext":{"head":"§44917. Deployment of Federal air marshals","paras":[[0,"(a) In General.—The Administrator of the Transportation Security Administration under the authority provided by section 44903(d)—"],[1,"(1) may provide for deployment of Federal air marshals on every passenger flight of air carriers in air transportation or intrastate air transportation;"],[1,"(2) shall provide for deployment of Federal air marshals on every such flight determined by the Administrator to present high security risks;"],[1,"(3) shall provide for appropriate training, supervision, and equipment of Federal air marshals;"],[1,"(4) shall require air carriers providing flights described in paragraph (1) to provide seating for a Federal air marshal on any such flight without regard to the availability of seats on the flight and at no cost to the United States Government or the marshal;"],[1,"(5) may require air carriers to provide, on a space-available basis, to an off-duty Federal air marshal a seat on a flight to the airport nearest the marshal's home at no cost to the marshal or the United States Government if the marshal is traveling to that airport after completing his or her security duties;"],[1,"(6) may enter into agreements with Federal, State, and local agencies under which appropriately-trained law enforcement personnel from such agencies, when traveling on a flight of an air carrier, will carry a firearm and be prepared to assist Federal air marshals;"],[1,"(7) shall establish procedures to ensure that Federal air marshals are made aware of any armed or unarmed law enforcement personnel on board an aircraft;"],[1,"(8) may appoint—"],[2,"(A) an individual who is a retired law enforcement officer;"],[2,"(B) an individual who is a retired member of the Armed Forces; and"],[2,"(C) an individual who has been furloughed from an air carrier crew position in the 1-year period beginning on September 11, 2001,"],[1,"as a Federal air marshal, regardless of age, if the individual otherwise meets the background and fitness qualifications required for Federal air marshals;"],[1,"(9) shall require the Federal Air Marshal Service to utilize a risk-based strategy when allocating resources between international and domestic flight coverage, including when initially setting its annual target numbers of average daily international and domestic flights to cover;"],[1,"(10) shall require the Federal Air Marshal Service to utilize a risk-based strategy to support domestic allocation decisions;"],[1,"(11) shall require the Federal Air Marshal Service to utilize a risk-based strategy to support international allocation decisions; and"],[1,"(12) shall ensure that the seating arrangements of Federal air marshals on aircraft are determined in a manner that is risk-based and most capable of responding to current threats to aviation security."],[0,"(b) Interim Measures.—Until the Under Secretary 1 completes implementation of subsection (a), the Under Secretary 1 may use, after consultation with and concurrence of the heads of other Federal agencies and departments, personnel from those agencies and departments, on a nonreimbursable basis, to provide air marshal service."],[0,"(c) Training for Foreign Law Enforcement Personnel.—"],[1,"(1) In general.—The Administrator of the Transportation Security Administration, after consultation with the Secretary of State, may direct the Federal Air Marshal Service to provide appropriate air marshal training to law enforcement personnel of foreign countries."],[1,"(2) Watchlist screening.—The Federal Air Marshal Service may only provide appropriate air marshal training to law enforcement personnel of foreign countries after comparing the identifying information and records of law enforcement personnel of foreign countries against all appropriate records in the consolidated and integrated terrorist watchlists maintained by the Federal Government."],[1,"(3) Fees.—The Administrator of the Transportation Security Administration shall establish reasonable fees and charges to pay expenses incurred in carrying out this subsection. Funds collected under this subsection shall be credited to the account in the Treasury from which the expenses were incurred and shall be available to the Administrator of the Transportation Security Administration for purposes for which amounts in such account are available."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/44917?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§44917. Deployment of Federal air marshals","tname":"Transportation","by":{"0":"6"}},{"t":"reg","label":"5 C.F.R. § 1200.1","url":"https://www.ecfr.gov/current/title-5/section-1200.1","by":{"0":"9"}},{"t":"reg","label":"14 C.F.R. pt. 191","url":"https://www.ecfr.gov/current/title-14/part-191","by":{"0":"3, 3"}},{"t":"reg","label":"70 Fed. Reg. 1380","url":"https://www.govinfo.gov/link/fr/70/1380","by":{"0":"6"}},{"t":"case","label":"Aquino v. Department of Homeland Sec.","cite":"121 M.S.P.R. 35","y":2014,"url":"https://www.courtlistener.com/c/M.S.P.R./121/35/","sum":"Concluding that a disclosure of “concerns about * * * moving the line control stanchions” at an airport screening checkpoint was covered by Section 2302(b)(8) largely because the fact that the government screens passengers in itself reflected the “seriousness” and “immi- nence” of the dangers that the employee claimed to be trying to prevent.","sumSrc":"brief:1","by":{"1":"18"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"131 S. Ct. 1068","y":2011,"id":"2010/09-152","sc":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"case","label":"Chambers v. Department of Interior","cite":"602 F.3d 1370","y":2010,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/602/1370/","by":{"1":"18"}},{"t":"case","label":"Department of the Navy v. Egan","cite":"484 U.S. 518","y":1988,"id":"1987/86-1552","sc":1,"sum":"In an appeal pursuant to § 7513, the Board does not have authority to review the substance of an underlying security-clearance determination in the course of reviewing an adverse action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6"}},{"t":"case","label":"Kent v. GSA","cite":"56 M.S.P.R. 536","y":1993,"url":"https://www.courtlistener.com/c/M.S.P.R./56/536/","op":1,"by":{"1":"8"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"9"}},{"t":"law","label":"Pub. L. No. 105-339","url":"https://www.govinfo.gov/link/plaw/105/public/339","by":{"1":"5"}},{"t":"usc","label":"6 U.S.C. § 133","url":"https://www.law.cornell.edu/uscode/text/6/133","subs":["(a)"],"by":{"1":"15"}},{"t":"usc","label":"40 U.S.C. § 486","url":"https://www.law.cornell.edu/uscode/text/40/486","subs":["(c)(1994)"],"by":{"1":"8"}},{"t":"usc","label":"49 U.S.C. § 46110","url":"https://www.law.cornell.edu/uscode/text/49/46110","by":{"1":"22"}},{"t":"usc","label":"50 U.S.C. § 435","url":"https://www.law.cornell.edu/uscode/text/50/435","by":{"1":"20"}},{"t":"reg","label":"3 C.F.R. pt. 396","url":"https://www.ecfr.gov/current/title-3/part-396","by":{"1":"20"}},{"t":"reg","label":"3 C.F.R. pt. 298","url":"https://www.ecfr.gov/current/title-3/part-298","by":{"1":"21"}},{"t":"reg","label":"3 C.F.R. pt. 267","url":"https://www.ecfr.gov/current/title-3/part-267","by":{"1":"16"}},{"t":"reg","label":"32 C.F.R. § 2001.43","url":"https://www.ecfr.gov/current/title-32/section-2001.43","by":{"1":"21"}}]};